<?php use App\Core\Security;?><div class="card mb-3"><div class="card-body"><h5>واحدهای اندازه‌گیری</h5><form method="post" action="/pricing/public/admin/units" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col"><input name="name" class="form-control" placeholder="نام واحد" required></div><div class="col"><input name="code" class="form-control" placeholder="کد"></div><div class="col-auto"><button class="btn btn-primary">ثبت</button></div></form></div></div><table class="table table-bordered"><tr><th>نام</th><th>کد</th><th>وضعیت</th></tr><?php foreach($units as $u):?><tr><td><?=Security::e($u['name'])?></td><td><?=Security::e($u['code'])?></td><td><?=$u['is_active']?'فعال':'غیرفعال'?></td></tr><?php endforeach;?></table>